widget.solution:
#include <vector>

std::vector<double> moving_average(const std::vector<double>& xs, int n) {
    std::vector<double> out;
    if (n < 1 || static_cast<std::size_t>(n) > xs.size()) {
        return out;
    }
    double sum = 0;
    for (std::size_t i = 0; i < xs.size(); ++i) {
        sum += xs[i];
        if (i >= static_cast<std::size_t>(n)) {
            sum -= xs[i - n];
        }
        if (i + 1 >= static_cast<std::size_t>(n)) {
            out.push_back(sum / n);
        }
    }
    return out;
}

