widget.solution:
#include <vector>

std::vector<double> returns_from(const std::vector<double>& px) {
    std::vector<double> out;
    if (px.size() < 2) {
        return out;
    }
    out.reserve(px.size() - 1);
    for (std::size_t i = 1; i < px.size(); ++i) {
        out.push_back(px[i] / px[i - 1] - 1);
    }
    return out;
}

