widget.solution:
#include <vector>

std::vector<std::vector<double>> price_lattice(double s0, double u, double d, int steps) {
    std::vector<std::vector<double>> tree;
    tree.reserve(steps + 1);
    tree.push_back({s0});
    for (int i = 1; i <= steps; ++i) {
        const std::vector<double>& prev = tree.back();
        std::vector<double> row;
        row.reserve(i + 1);
        row.push_back(prev[0] * u);
        for (int j = 0; j < i; ++j) {
            row.push_back(prev[j] * d);
        }
        tree.push_back(row);
    }
    return tree;
}
